import Foundation

/// Meeting minutes style artifact generated by an LLM when a session ends. Not to be confused
/// with `SessionDebrief` (heuristic coaching oriented) which remains available alongside.
struct SessionSummary: Codable, Equatable {
    enum Status: String, Codable, CaseIterable {
        case pending
        case generating
        case completed
        case failed
        case heuristic
    }

    struct ActionItem: Identifiable, Codable, Equatable {
        let id: UUID
        var title: String
        var owner: String?
        var dueDate: String?
        var notes: String?

        init(
            id: UUID = UUID(),
            title: String,
            owner: String? = nil,
            dueDate: String? = nil,
            notes: String? = nil
        ) {
            self.id = id
            self.title = title
            self.owner = owner
            self.dueDate = dueDate
            self.notes = notes
        }
    }

    let sessionID: UUID
    var status: Status
    var actionItems: [ActionItem]
    var backgroundSummary: String
    var followUpEmailDraft: String?
    var generatedAt: Date?
    var errorMessage: String?

    init(
        sessionID: UUID,
        status: Status = .pending,
        actionItems: [ActionItem] = [],
        backgroundSummary: String = "",
        followUpEmailDraft: String? = nil,
        generatedAt: Date? = nil,
        errorMessage: String? = nil
    ) {
        self.sessionID = sessionID
        self.status = status
        self.actionItems = actionItems
        self.backgroundSummary = backgroundSummary
        self.followUpEmailDraft = followUpEmailDraft
        self.generatedAt = generatedAt
        self.errorMessage = errorMessage
    }

    var isPopulated: Bool {
        !actionItems.isEmpty || !backgroundSummary.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }
}
